$(document).ready(function () {
    const APP_URLAPP = window.location.origin;
    const rootContainer = document.querySelector('.opac-v2-root');
    const urlParams = new URLSearchParams(window.location.search);
    const state = {
        q: (urlParams.get('q') || '').trim(),
        category: (urlParams.get('category') || 'sembarang').trim(),
        page: 1,
        perPage: 10,
        authors: [],
        publishers: [],
        publishLocations: [],
        worksheetIds: [],
        libraryLocations: [],
        worksheetLabelMap: {}
    };
    let hasTriggeredSearch = false;
    let currentDisplayMode = null;
    let displayTransitionToken = 0;

    $('#keyword').val(state.q);
    $('#category').val(state.category);

    const escapeHtml = (text) => $(' ').text(text || '').html();

    function normalizeCoverFileName(coverUrl) {
        let cover = (coverUrl || '').toString().trim();
        if (!cover) return 'nophoto.jpg';

        // If the source stores plain numeric IDs, default to jpg.
        if (/^\d+$/.test(cover)) {
            cover += '.jpg';
        }

        // Remove accidental leading slash and spaces.
        cover = cover.replace(/^\/+/, '');
        return cover || 'nophoto.jpg';
    }

    function getCoverUrl(coverUrl) {
        const cover = normalizeCoverFileName(coverUrl);
        // Sumber utama: public/assets_user/img/catalogs (sama dengan admin upload & legacy)
        return APP_URLAPP + '/assets_user/img/catalogs/' + encodeURIComponent(cover);
    }

    function renderFacet(containerId, inputName, buckets, selectedValues) {
        const el = $(containerId);
        if (!buckets || buckets.length === 0) {
            el.html(' Tidak ada data. ');
            return;
        }

        const visibleLimit = 8;
        let html = '';
        buckets.forEach((item, index) => {
            if (!item.key) return;
            const label = item.label || item.key;
            const key = String(item.key);
            const activeClass = selectedValues.map(String).includes(key) ? 'active' : '';
            const hiddenClass = index >= visibleLimit ? 'facet-hidden' : '';
            html += ` ${escapeHtml(label)} ${item.doc_count} `;
        });

        if (buckets.length > visibleLimit) {
            html += ` Lihat lebih banyak `;
        }

        el.html(html);

        if (inputName === 'facet_worksheets') {
            const map = {};
            buckets.forEach((item) => {
                map[String(item.key)] = item.label || item.key;
            });
            state.worksheetLabelMap = map;
        }
    }

    function filterChipHtml(cssMod, typeKey, value, labelHtml) {
        const enc = encodeURIComponent(String(value));
        return (
            ` ` +
            ` ${labelHtml} ` +
            ` ` +
            ` ` +
            ` `
        );
    }

    function renderActiveFilterBadges() {
        const badges = [];
        state.authors.forEach((v) =>
            badges.push(filterChipHtml('author', 'authors', v, `Pengarang: ${escapeHtml(v)}`))
        );
        state.publishers.forEach((v) =>
            badges.push(filterChipHtml('publisher', 'publishers', v, `Penerbit: ${escapeHtml(v)}`))
        );
        state.publishLocations.forEach((v) =>
            badges.push(filterChipHtml('place', 'publish_locations', v, `Lokasi terbit: ${escapeHtml(v)}`))
        );
        state.worksheetIds.forEach((v) => {
            const label = state.worksheetLabelMap[String(v)] || v;
            badges.push(filterChipHtml('type', 'worksheet_ids', v, `Jenis: ${escapeHtml(label)}`));
        });
        state.libraryLocations.forEach((v) =>
            badges.push(filterChipHtml('lib', 'library_locations', v, `Perpustakaan: ${escapeHtml(v)}`))
        );
        $('#active-filter-badges').html(badges.join(''));
    }

    function removeActiveFacet(type, encodedValue) {
        let raw;
        try {
            raw = decodeURIComponent(encodedValue);
        } catch (e) {
            return;
        }
        const val = String(raw);

        if (type === 'authors') {
            state.authors = state.authors.filter((x) => String(x) !== val);
        } else if (type === 'publishers') {
            state.publishers = state.publishers.filter((x) => String(x) !== val);
        } else if (type === 'publish_locations') {
            state.publishLocations = state.publishLocations.filter((x) => String(x) !== val);
        } else if (type === 'worksheet_ids') {
            state.worksheetIds = state.worksheetIds.filter((x) => String(x) !== val);
        } else if (type === 'library_locations') {
            state.libraryLocations = state.libraryLocations.filter((x) => String(x) !== val);
        } else {
            return;
        }

        state.q = ($('#keyword').val() || '').trim();
        state.category = $('#category').val() || 'sembarang';
        state.page = 1;

        if (state.q === '' && !hasAnyFilterSelected()) {
            resetToHomeDefault();
            return;
        }
        fetchSearch();
    }

    function renderResults(data) {
        const list = $('#opac-result-list');
        if (!data || data.length === 0) {
            list.html(' Data tidak ditemukan. Coba kata kunci atau filter lain. ');
            list.removeClass('is-loading');
            return;
        }

        let html = '';
        data.forEach((book) => {
            const catalogId = book.CatalogId || '';
            const title = book.judul_buku || '-';
            const author = book.author || '-';
            const publisher = [book.publisher, book.PublishLocation, book.PublishYear].filter(Boolean).join(' ');
            const worksheet = book.worksheet || '-';
            const callNumber = book.callNumber || '-';
            const digital = book.KONTEN_DIGITAL || 'Tidak ada data';
            const available = Number(book.JML_BUKU || 0);
            const total = Number(book.ALL_BUKU || 0);

            html += ` ${escapeHtml(title)} Jenis ${escapeHtml(worksheet)} Pengarang ${escapeHtml(author)} Penerbit ${escapeHtml(publisher || '-')} Nomor panggil ${escapeHtml(callNumber)} Konten digital ${escapeHtml(digital)} Ketersediaan: ${available} dari ${total} eksemplar `;
        });

        list.html(html);
        list.find('.opac-result-animate').each(function (index) {
            const el = this;
            setTimeout(function () {
                el.classList.add('is-visible');
            }, index * 35);
        });
        list.removeClass('is-loading');
    }

    function renderPagination(meta) {
        const container = $('#opac-pagination');
        const totalPages = Number(meta.total_pages || 0);
        const currentPage = Number(meta.page || 1);

        if (totalPages <= 1) {
            container.html('');
            return;
        }

        const startPage = Math.max(1, currentPage - 2);
        const endPage = Math.min(totalPages, startPage + 4);
        let html = ' ';

        const prevDisabled = currentPage <= 1 ? 'disabled' : '';
        html += ` Prev `;

        for (let i = startPage; i <= endPage; i++) {
            const active = i === currentPage ? 'active' : '';
            html += ` ${i} `;
        }

        const nextDisabled = currentPage >= totalPages ? 'disabled' : '';
        html += ` Next `;
        html += ' ';
        container.html(html);
    }

    function updateSummary(meta) {
        const total = Number(meta.total || 0);
        const page = Number(meta.page || 1);
        const perPage = Number(meta.per_page || 10);
        const firstItem = total === 0 ? 0 : ((page - 1) * perPage) + 1;
        const lastItem = Math.min(page * perPage, total);
        $('#search-summary').text(`Menampilkan ${firstItem} - ${lastItem} dari ${total} hasil`);
    }

    function hasAnyFilterSelected() {
        return (
            state.authors.length > 0 ||
            state.publishers.length > 0 ||
            state.publishLocations.length > 0 ||
            state.worksheetIds.length > 0 ||
            state.libraryLocations.length > 0
        );
    }

    function smoothShow($el, duration) {
        return new Promise(function (resolve) {
            if (!$el || $el.length === 0) {
                resolve();
                return;
            }

            $el.stop(true, true);
            $el.removeClass('d-none');
            $el.css({ opacity: 0, transform: 'translateY(10px)' });
            $el.show();
            $el.animate({ opacity: 1 }, {
                duration: duration || 300,
                queue: false,
                complete: function () {
                    $el.css({ opacity: '', transform: '' });
                    resolve();
                }
            });
            requestAnimationFrame(function () {
                $el.css('transform', 'translateY(0)');
            });
        });
    }

    function smoothHide($el, duration) {
        return new Promise(function (resolve) {
            if (!$el || $el.length === 0) {
                resolve();
                return;
            }

            if ($el.hasClass('d-none') || !$el.is(':visible')) {
                $el.addClass('d-none');
                resolve();
                return;
            }

            $el.stop(true, true);
            $el.css({ opacity: 1, transform: 'translateY(0)' });
            $el.animate({ opacity: 0 }, {
                duration: duration || 220,
                queue: false,
                complete: function () {
                    $el.addClass('d-none').css({ display: '', opacity: '', transform: '' });
                    resolve();
                }
            });
            requestAnimationFrame(function () {
                $el.css('transform', 'translateY(10px)');
            });
        });
    }

    function setDisplayMode(isSearchMode, useAnimation) {
        const searchPanel = $('#opac-search-panel');
        const popularSection = $('#opac-popular-section');
        const latestSection = $('#opac-latest-section');
        const homeDefaultButton = $('#btn-home-default');
        const animate = useAnimation !== false;
        const nextMode = isSearchMode ? 'search' : 'home';
        const token = ++displayTransitionToken;

        if (currentDisplayMode === nextMode) {
            if (isSearchMode) {
                homeDefaultButton.removeClass('d-none');
            } else {
                homeDefaultButton.addClass('d-none');
            }
            return;
        }

        if (isSearchMode) {
            if (!animate) {
                searchPanel.removeClass('d-none');
                popularSection.addClass('d-none');
                latestSection.addClass('d-none');
                homeDefaultButton.removeClass('d-none');
                currentDisplayMode = nextMode;
                return;
            }
            Promise.all([
                smoothHide(popularSection, 220),
                smoothHide(latestSection, 220)
            ]).then(function () {
                if (token !== displayTransitionToken) return;
                smoothShow(searchPanel, 320).then(function () {
                    if (token !== displayTransitionToken) return;
                    homeDefaultButton.removeClass('d-none');
                    currentDisplayMode = nextMode;
                });
            });
            return;
        }

        if (!animate) {
            searchPanel.addClass('d-none');
            popularSection.removeClass('d-none');
            latestSection.removeClass('d-none');
            homeDefaultButton.addClass('d-none');
            currentDisplayMode = nextMode;
            return;
        }

        homeDefaultButton.addClass('d-none');
        smoothHide(searchPanel, 220).then(function () {
            if (token !== displayTransitionToken) return;
            Promise.all([
                smoothShow(popularSection, 320),
                smoothShow(latestSection, 320)
            ]).then(function () {
                if (token !== displayTransitionToken) return;
                currentDisplayMode = nextMode;
            });
        });
    }

    function resetToHomeDefault() {
        state.q = '';
        state.category = 'sembarang';
        state.page = 1;
        state.authors = [];
        state.publishers = [];
        state.publishLocations = [];
        state.worksheetIds = [];
        state.libraryLocations = [];
        state.worksheetLabelMap = {};
        hasTriggeredSearch = false;

        $('#keyword').val('');
        $('#category').val('sembarang');
        $('#facet-authors').html('');
        $('#facet-publishers').html('');
        $('#facet-publish-locations').html('');
        $('#facet-worksheets').html('');
        $('#facet-library-locations').html('');

        setDisplayMode(false);
        renderInitialHomeState();

        if (window.history && typeof window.history.replaceState === 'function') {
            window.history.replaceState({}, document.title, window.location.pathname);
        }
